function updateCarousel(){const step=track.firstElementChild.getBoundingClientRect().width+24;const index=Math.round(track.scrollLeft/step);document.querySelector('#project-count').textContent=`${String(index+1).padStart(2,'0')} / ${String(projects.length).padStart(2,'0')}`;document.querySelector('#progress-fill').style.width=`${Math.min(100,(track.scrollLeft+track.clientWidth)/track.scrollWidth*100)}%`;prev.disabled=track.scrollLeft<5;next.disabled=track.scrollLeft+track.clientWidth>=track.scrollWidth-5}
function move(direction){track.scrollBy({left:direction*(track.firstElementChild.getBoundingClientRect().width+24),behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})}
prev.addEventListener('click',()=>move(-1));next.addEventListener('click',()=>move(1));track.addEventListener('scroll',updateCarousel,{passive:true});window.addEventListener('resize',updateCarousel);track.addEventListener('keydown',event=>{if(event.key==='ArrowRight'||event.key==='ArrowLeft'){event.preventDefault();move(event.key==='ArrowRight'?1:-1)}});updateCarousel();
