const firstVideo=document.querySelector('#banner-video');
const videoToggle=document.querySelector('#video-toggle');
const motionPreference=matchMedia('(prefers-reduced-motion: reduce)');
const secondVideo=document.createElement('video');
secondVideo.muted=true;secondVideo.playsInline=true;secondVideo.preload='metadata';
secondVideo.setAttribute('aria-hidden','true');
firstVideo.after(secondVideo);
firstVideo.preload='metadata';
const players=[firstVideo,secondVideo];
let active=0,clip=1,wantsPlayback=false,transitioning=false;
firstVideo.style.opacity='1';firstVideo.style.zIndex='0';
secondVideo.style.opacity='0';secondVideo.style.zIndex='1';
secondVideo.src='assets/banner-2.mp4';secondVideo.load();
function syncVideoButton(){const label=wantsPlayback?'Пауза Ⅱ':'Пусни видеото ▶';videoToggle.textContent=label;videoToggle.setAttribute('aria-label',label)}
async function startPlayback(){wantsPlayback=true;syncVideoButton();try{await players[active].play()}catch{wantsPlayback=false;syncVideoButton()}}
function pausePlayback(){wantsPlayback=false;players.forEach(video=>video.pause());syncVideoButton()}
async function transitionClip(){
 if(transitioning||!wantsPlayback)return;
 const outgoing=players[active],incoming=players[1-active];
 if(incoming.readyState<3)return; // Keep the last frame until the next clip is buffered.
 transitioning=true;
 try{await incoming.play()}catch{transitioning=false;return;}
 if(!wantsPlayback){incoming.pause();transitioning=false;return;}
 const reveal=()=>{
  if(!wantsPlayback){incoming.pause();transitioning=false;return;}
  firstVideo.removeAttribute('poster');
  incoming.style.zIndex='1';outgoing.style.zIndex='0';
  incoming.style.transition='none';incoming.style.opacity='0';
  const fade=incoming.animate([{opacity:0},{opacity:1}],{duration:motionPreference.matches?0:1400,easing:'ease-in-out',fill:'forwards'});
  fade.finished.then(()=>{
   incoming.style.opacity='1';fade.cancel();
   outgoing.style.opacity='0';outgoing.pause();
   active=1-active;clip=clip%4+1;
   outgoing.src=`assets/banner-${clip%4+1}.mp4`;outgoing.load();
   transitioning=false;
   if(!wantsPlayback)incoming.pause();
  });
 };
 if(incoming.requestVideoFrameCallback)incoming.requestVideoFrameCallback(reveal);
 else requestAnimationFrame(reveal);
}
players.forEach(video=>{
 video.addEventListener('timeupdate',()=>{if(video===players[active]&&video.duration-video.currentTime<=1.6)transitionClip()});
 video.addEventListener('ended',()=>{if(video===players[active])transitionClip()});
 video.addEventListener('canplay',()=>{if(players[active].ended)transitionClip()});
});
videoToggle.addEventListener('click',()=>wantsPlayback?pausePlayback():startPlayback());
motionPreference.addEventListener('change',event=>{if(event.matches)pausePlayback()});
if(!motionPreference.matches)startPlayback();


// Play construction frames while visible; resume or replay on re-entry.
const buildStory=document.querySelector('#build-story');
const buildImage=document.querySelector('#build-frame');
const buildReplay=document.querySelector('#build-replay');
const frames=new Map(),frameCount=80,duration=8000;
let elapsed=0,lastTime=null,frameRequest=0,visible=false,finished=false,playing=false,wanted=0;
function frameUrl(index){return `assets/build-frames/frame-${String(index+1).padStart(3,'0')}.jpg`}
function getFrame(index){if(frames.has(index))return frames.get(index);const img=new Image();const promise=new Promise(resolve=>{img.onload=()=>resolve(img);img.onerror=()=>{frames.delete(index);resolve(null)}});frames.set(index,promise);img.src=frameUrl(index);return promise}
async function displayFrame(index){wanted=index;const img=await getFrame(index);if(img&&wanted===index)buildImage.src=img.src}
let preloading=false;
function preload(){if(preloading)return;preloading=true;let cursor=0;Promise.all(Array.from({length:4},async()=>{while(cursor<frameCount)await getFrame(cursor++)}))}
function pauseBuild(){playing=false;cancelAnimationFrame(frameRequest);lastTime=null;buildReplay.textContent=finished?'Пусни отново ↻':'Продължи ▶'}
function tick(time){if(!playing)return;if(lastTime!==null)elapsed+=time-lastTime;lastTime=time;displayFrame(Math.min(79,Math.floor(elapsed/duration*79)));if(elapsed>=duration){finished=true;pauseBuild();return}frameRequest=requestAnimationFrame(tick)}
function playBuild(){if(playing)return;preload();if(finished){elapsed=0;finished=false;displayFrame(0)}playing=true;lastTime=null;buildReplay.textContent='Пауза Ⅱ';frameRequest=requestAnimationFrame(tick)}
buildReplay.addEventListener('click',()=>playing?pauseBuild():playBuild());
function setBuildVisible(value){if(value===visible)return;visible=value;if(!visible)pauseBuild();else if(!motionPreference.matches&&!document.hidden)playBuild()}
const observer=new IntersectionObserver(entries=>setBuildVisible(entries[0].isIntersecting&&entries[0].intersectionRatio>=.35),{threshold:[0,.35]});observer.observe(buildStory);
document.addEventListener('visibilitychange',()=>{if(document.hidden)pauseBuild();else if(visible&&!motionPreference.matches)playBuild()});
motionPreference.addEventListener('change',()=>{if(motionPreference.matches)pauseBuild();else if(visible)playBuild()});
buildReplay.textContent='Пусни анимацията ▶';

// Touch screens have no hover state, so material effects play while their section is in view.
const materialEffects=Array.from(document.querySelectorAll('.approach,.contact,.stage-explorer,.package-grid article'));
const mobileEffects=window.matchMedia('(max-width:760px)');
const materialEffectObserver=new IntersectionObserver(entries=>{
 if(!mobileEffects.matches||motionPreference.matches)return;
 entries.forEach(entry=>entry.target.classList.toggle('material-effect-active',entry.isIntersecting&&entry.intersectionRatio>=.35));
},{threshold:[0,.35]});
materialEffects.forEach(element=>materialEffectObserver.observe(element));
mobileEffects.addEventListener('change',event=>{
 materialEffects.forEach(element=>{
  if(!event.matches)element.classList.remove('material-effect-active');
 });
});

let activeProjectIndex=0,activeProjectImage=0;const baseOpenProject=openProject;openProject=function(index){activeProjectIndex=index;activeProjectImage=0;baseOpenProject(index);updateProjectGallery()};function updateProjectGallery(){const p=projects[activeProjectIndex],image=document.querySelector('#project-modal-image');image.src=p.gallery[activeProjectImage];image.alt=`${p.name} — реализиран проект, снимка ${activeProjectImage+1}`;document.querySelector('#project-gallery-count').textContent=(activeProjectImage+1)+' / '+p.gallery.length}document.querySelector('#project-gallery-prev').addEventListener('click',()=>{const p=projects[activeProjectIndex];activeProjectImage=(activeProjectImage+p.gallery.length-1)%p.gallery.length;updateProjectGallery()});document.querySelector('#project-gallery-next').addEventListener('click',()=>{const p=projects[activeProjectIndex];activeProjectImage=(activeProjectImage+1)%p.gallery.length;updateProjectGallery()});



const projectGallerySurface=document.querySelector('.project-modal-image');let galleryTouchStartX=null,galleryTouchStartY=null;projectGallerySurface.addEventListener('touchstart',event=>{const touch=event.changedTouches[0];galleryTouchStartX=touch.clientX;galleryTouchStartY=touch.clientY},{passive:true});projectGallerySurface.addEventListener('touchend',event=>{if(galleryTouchStartX===null)return;const touch=event.changedTouches[0],dx=touch.clientX-galleryTouchStartX,dy=touch.clientY-galleryTouchStartY;galleryTouchStartX=null;if(Math.abs(dx)>48&&Math.abs(dx)>Math.abs(dy)){const project=projects[activeProjectIndex];activeProjectImage=(activeProjectImage+(dx<0?1:project.gallery.length-1))%project.gallery.length;updateProjectGallery()}},{passive:true});

const requestedProject=new URLSearchParams(window.location.search).get('project');if(requestedProject!==null&&Number.isInteger(Number(requestedProject))&&projects[Number(requestedProject)]){setTimeout(()=>openProject(Number(requestedProject)),0)}
